contract KCC20V3(
    byte[32] stateOwner,
    int stateAmount,
    int stateMode,
    int marketUnitPriceSompi
) {
    int constant MODE_HOLDER = 0;
    int constant MODE_ROOT = 1;
    int constant MODE_ASK = 2;
    int constant MODE_BID = 3;

    byte[32] owner = stateOwner;
    int amount = stateAmount;
    int mode = stateMode;
    int unitPrice = marketUnitPriceSompi;
    byte[32] constant FEE_RECIPIENT = 0xce2100e68197c8e695bd781d07e2bd5de7ed77f5a97668884190531bdc632c01;
    int constant MIN_PROTOCOL_FEE_SOMPI = 50000000;
    int constant MIN_FILL_GROSS_SOMPI = 50000000;

    function requireRoot() {
        require(mode == MODE_ROOT);
        require(amount >= 0);
        require(unitPrice == 0);
    }

    function requireHolder() {
        require(mode == MODE_HOLDER);
        require(amount > 0);
    }

    function requireAsk() {
        require(mode == MODE_ASK);
        require(amount > 0);
        require(unitPrice > 0);
    }

    function requireBid() {
        require(mode == MODE_BID);
        require(amount > 0);
        require(unitPrice > 0);
        require(tx.inputs[this.activeInputIndex].value == amount * unitPrice);
    }

    function stateOutput(byte[32] outOwner, int outAmount, int outMode, int outUnitPrice, int outputIndex) {
        validateOutputState(outputIndex, {
            owner: outOwner,
            amount: outAmount,
            mode: outMode,
            unitPrice: outUnitPrice
        });
    }

    function holderOutput(byte[32] outOwner, int outAmount, int outputIndex) {
        stateOutput(outOwner, outAmount, MODE_HOLDER, 0, outputIndex);
    }

    function rootOutput(int outAmount, int outputIndex) {
        stateOutput(owner, outAmount, MODE_ROOT, 0, outputIndex);
    }

    function askOutput(int outAmount, int outputIndex) {
        stateOutput(owner, outAmount, MODE_ASK, unitPrice, outputIndex);
    }

    function bidOutput(byte[32] outOwner, int outAmount, int outputIndex) {
        stateOutput(outOwner, outAmount, MODE_BID, unitPrice, outputIndex);
        require(tx.outputs[outputIndex].value == outAmount * unitPrice);
    }

    function requireFill(int fillAmount, int remainingAmount) {
        require(fillAmount > 0);
        require(fillAmount <= amount);
        int grossSompi = unitPrice * fillAmount;
        require(grossSompi >= MIN_FILL_GROSS_SOMPI);
        if (remainingAmount > 0) {
            require(unitPrice * remainingAmount >= MIN_FILL_GROSS_SOMPI);
        }
    }

    function feeForGross(int grossSompi): int {
        int feeSompi = grossSompi / 50;
        if (feeSompi < MIN_PROTOCOL_FEE_SOMPI) {
            feeSompi = MIN_PROTOCOL_FEE_SOMPI;
        }
        return feeSompi;
    }

    function requireFeeAt(int feeSompi, int feeOutputIndex) {
        if (feeSompi > 0) {
            require(tx.outputs[feeOutputIndex].value == feeSompi);
            require(tx.outputs[feeOutputIndex].scriptPubKey == byte[](new ScriptPubKeyP2PK(pubkey(FEE_RECIPIENT))));
        }
    }

    entrypoint function issueFromRoot(sig issuerSig, byte[32] toOwner, int tokenAmount, int tokenOutputIndex, int rootOutputIndex) {
        requireRoot();
        require(checkSig(issuerSig, pubkey(owner)));
        require(tokenAmount > 0);
        require(tokenAmount <= amount);
        require(OpAuthOutputCount(this.activeInputIndex) == 2);
        require(OpAuthOutputIdx(this.activeInputIndex, 0) == tokenOutputIndex);
        require(OpAuthOutputIdx(this.activeInputIndex, 1) == rootOutputIndex);
        require(tx.outputs[rootOutputIndex].value == tx.inputs[this.activeInputIndex].value);
        holderOutput(toOwner, tokenAmount, tokenOutputIndex);
        rootOutput(amount - tokenAmount, rootOutputIndex);
    }

    entrypoint function createBidFromRoot(byte[32] buyer, int bidAmount, int bidUnitPrice, int bidOutputIndex, int rootOutputIndex) {
        requireRoot();
        require(bidAmount > 0);
        require(bidUnitPrice > 0);
        require(bidAmount * bidUnitPrice >= MIN_FILL_GROSS_SOMPI);
        require(OpAuthOutputCount(this.activeInputIndex) == 2);
        require(OpAuthOutputIdx(this.activeInputIndex, 0) == bidOutputIndex);
        require(OpAuthOutputIdx(this.activeInputIndex, 1) == rootOutputIndex);
        require(tx.outputs[rootOutputIndex].value == tx.inputs[this.activeInputIndex].value);
        stateOutput(buyer, bidAmount, MODE_BID, bidUnitPrice, bidOutputIndex);
        require(tx.outputs[bidOutputIndex].value == bidAmount * bidUnitPrice);
        rootOutput(amount, rootOutputIndex);
    }

    entrypoint function createAskByOwnerSig(sig ownerSig, int askAmount, int askUnitPrice, int askOutputIndex, int changeOutputIndex) {
        requireHolder();
        require(checkSig(ownerSig, pubkey(owner)));
        require(askAmount > 0);
        require(askAmount <= amount);
        require(askUnitPrice > 0);
        require(askAmount * askUnitPrice >= MIN_FILL_GROSS_SOMPI);
        stateOutput(owner, askAmount, MODE_ASK, askUnitPrice, askOutputIndex);
        if (askAmount < amount) {
            require(OpAuthOutputCount(this.activeInputIndex) == 2);
            require(OpAuthOutputIdx(this.activeInputIndex, 0) == askOutputIndex);
            require(OpAuthOutputIdx(this.activeInputIndex, 1) == changeOutputIndex);
            holderOutput(owner, amount - askAmount, changeOutputIndex);
