    entrypoint function fillAskPartial(byte[32] buyer, int fillAmount, int buyerOutputIndex, int askOutputIndex, int sellerOutputIndex) {
        requireAsk();
        int remainingAmount = amount - fillAmount;
        requireFill(fillAmount, remainingAmount);
        int grossSompi = unitPrice * fillAmount;
        int feeSompi = feeForGross(grossSompi);
        int sellerNetSompi = grossSompi - feeSompi;
        int sellerValueSompi = sellerNetSompi;
        holderOutput(buyer, fillAmount, buyerOutputIndex);
        if (remainingAmount > 0) {
            require(OpAuthOutputCount(this.activeInputIndex) == 2);
            require(OpAuthOutputIdx(this.activeInputIndex, 0) == buyerOutputIndex);
            require(OpAuthOutputIdx(this.activeInputIndex, 1) == askOutputIndex);
            require(tx.outputs[askOutputIndex].value == tx.inputs[this.activeInputIndex].value);
            askOutput(remainingAmount, askOutputIndex);
        } else {
            require(OpAuthOutputCount(this.activeInputIndex) == 1);
            require(OpAuthOutputIdx(this.activeInputIndex, 0) == buyerOutputIndex);
            sellerValueSompi = tx.inputs[this.activeInputIndex].value + sellerNetSompi;
        }
        if (sellerValueSompi > 0) {
            require(tx.outputs[sellerOutputIndex].value == sellerValueSompi);
            require(tx.outputs[sellerOutputIndex].scriptPubKey == byte[](new ScriptPubKeyP2PK(pubkey(owner))));
            requireFeeAt(feeSompi, sellerOutputIndex + 1);
        } else {
            requireFeeAt(feeSompi, sellerOutputIndex);
        }
    }

    entrypoint function fillBidPartial(int sellerInputIndex, int fillAmount, int buyerOutputIndex, int bidOutputIndex, int sellerOutputIndex, pubkey seller) {
        requireBid();
        require(sellerInputIndex != this.activeInputIndex);
        require(OpInputCovenantId(sellerInputIndex) == OpInputCovenantId(this.activeInputIndex));
        require(OpAuthOutputCount(sellerInputIndex) >= 1);
        require(OpAuthOutputIdx(sellerInputIndex, 0) == buyerOutputIndex);
        int remainingAmount = amount - fillAmount;
        requireFill(fillAmount, remainingAmount);
        int grossSompi = unitPrice * fillAmount;
        int feeSompi = feeForGross(grossSompi);
        int sellerNetSompi = grossSompi - feeSompi;
        int sellerValueSompi = sellerNetSompi;
        holderOutput(owner, fillAmount, buyerOutputIndex);
        if (remainingAmount > 0) {
            require(OpAuthOutputCount(this.activeInputIndex) == 1);
            require(OpAuthOutputIdx(this.activeInputIndex, 0) == bidOutputIndex);
            bidOutput(owner, remainingAmount, bidOutputIndex);
            require(tx.outputs[bidOutputIndex].value == tx.inputs[this.activeInputIndex].value - grossSompi);
        } else {
            require(OpAuthOutputCount(this.activeInputIndex) == 0);
            sellerValueSompi = tx.inputs[this.activeInputIndex].value - feeSompi;
        }
        if (sellerValueSompi > 0) {
            require(tx.outputs[sellerOutputIndex].value == sellerValueSompi);
            require(tx.outputs[sellerOutputIndex].scriptPubKey == byte[](new ScriptPubKeyP2PK(seller)));
            requireFeeAt(feeSompi, sellerOutputIndex + 1);
        } else {
            requireFeeAt(feeSompi, sellerOutputIndex);
        }
    }

    entrypoint function sellIntoBidByOwnerSig(sig ownerSig, byte[32] buyer, int fillAmount, int buyerOutputIndex, int changeOutputIndex) {
        requireHolder();
        require(checkSig(ownerSig, pubkey(owner)));
        require(fillAmount > 0);
        require(fillAmount <= amount);
        holderOutput(buyer, fillAmount, buyerOutputIndex);
        if (fillAmount < amount) {
            require(OpAuthOutputCount(this.activeInputIndex) == 2);
            require(OpAuthOutputIdx(this.activeInputIndex, 0) == buyerOutputIndex);
            require(OpAuthOutputIdx(this.activeInputIndex, 1) == changeOutputIndex);
            holderOutput(owner, amount - fillAmount, changeOutputIndex);
        } else {
            require(OpAuthOutputCount(this.activeInputIndex) == 1);
            require(OpAuthOutputIdx(this.activeInputIndex, 0) == buyerOutputIndex);
        }
    }
}
